#include <algorithm>
#include <cstdint>
#include <vector>

int mulDiv(int number, int numerator, int denominator)
{
    if (denominator == 0) return -1;
    const std::int64_t product{ static_cast<std::int64_t>(number) * numerator };
    const bool negative{ (product < 0) != (denominator < 0) };
    const std::int64_t p{ product < 0 ? -product : product }, d{ denominator < 0 ? -static_cast<std::int64_t>(denominator) : denominator };
    const std::int64_t q{ (p + d / 2) / d };
    return static_cast<int>(negative ? -q : q);
}

int scaleForDpi(int value96, int dpi) { return mulDiv(value96, dpi, 96); }
int fontHeight(int points, int dpi) { return -mulDiv(points, dpi, 72); }

int pickIconSize(const std::vector<int>& available, int wanted)
{
    if (available.empty()) return 0;
    int best{ 0 };
    for (int s : available) if (s >= wanted && (best == 0 || s < best)) best = s;
    return best != 0 ? best : *std::max_element(available.begin(), available.end());
}

