TEST("MulDiv rounding") {
    CHECK_EQ(mulDiv(3, 1, 2), 2); CHECK_EQ(mulDiv(-3, 1, 2), -2); CHECK_EQ(mulDiv(5, 3, 4), 4); CHECK_EQ(mulDiv(1, 1, 3), 0); CHECK_EQ(mulDiv(7, 1, 0), -1);
    CHECK_EQ(mulDiv(2'000'000'000, 3, 4), 1'500'000'000); CHECK_EQ(mulDiv(10, -3, 4), -8);
}
TEST("scaling") { CHECK_EQ(scaleForDpi(10, 144), 15); CHECK_EQ(scaleForDpi(80, 120), 100); CHECK_EQ(scaleForDpi(7, 144), 11); CHECK_EQ(scaleForDpi(16, 192), 32); CHECK_EQ(scaleForDpi(1, 168), 2); }
TEST("scale from the design value") { CHECK_EQ(scaleForDpi(7, 120), 9); CHECK_EQ(mulDiv(9, 96, 120), 7); CHECK_EQ(scaleForDpi(5, 144), 8); CHECK_EQ(mulDiv(8, 120, 144), 7); CHECK_EQ(scaleForDpi(5, 120), 6); }
TEST("fonts") { CHECK_EQ(fontHeight(9, 96), -12); CHECK_EQ(fontHeight(9, 144), -18); CHECK_EQ(fontHeight(11, 120), -18); }
TEST("icons") { const std::vector<int> sizes{ 48, 16, 256, 32, 24 }; CHECK_EQ(pickIconSize(sizes, 20), 24); CHECK_EQ(pickIconSize(sizes, 32), 32); CHECK_EQ(pickIconSize(sizes, 300), 256); CHECK_EQ(pickIconSize({}, 16), 0); }

